entries[221903] = { ["name"] = "Prototype: Tinker: Earthen Delivery Drill", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Summon an Earthen Delivery Drill to dig for an assortment of battleground buffs.\n\nThe drill lasts for 28 sec and can only be summoned while in combat. Can only be used in unrated battlegrounds and in War Mode on Khaz Algar. (15 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:" }
