entries[221907] = { ["name"] = "Prototype: Tinker: Heartseeking Health Injector", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Inject a medicinal frostfire formula into your veins, instantly healing you for up to 1943637 from a jolt of frost. To prevent sudden hypothermia, you will then burn for 30% of the amount healed.\n\nShares a cooldown with healing potions.\nRequires Khaz Algar Engineering (1)\nSell Price:" }
entries[221908] = { ["name"] = "Tinker: Heartseeking Health Injector", ["text"] = "Tinker Module\nUnique-Equipped: Heartseeking Health Injector (1)\nHeartseeking Health Injector\nEquip: Insert into a Tinker Socket for the following effect:\n\nHeartseeking Health Injector\nInject a medicinal frostfire formula into your veins, instantly healing you for up to 32012 from a jolt of frost. To prevent sudden hypothermia, you will then burn for 30% of the amount healed.\n\nShares a cooldown with healing potions.\n\"Tinker quality and engineering specialization impact success chance. With proper precautions, this tinker cannot malfunction. This warranty only applies to Algari equipment.\"\nSell Price:" }
