entries[221944] = { ["name"] = "Prototype: Irresistible Red Button", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Deploy a device that can be activated by you or a party or raid member when a crisis is imminent. When activated, it will attempt to resurrect all nearby allies at the end of combat.\n\nLasts for 1 hour or until activation. Must be deployed prior to combat.\nRequires Khaz Algar Engineering (1)\nSell Price:" }
entries[221945] = { ["name"] = "Irresistible Red Button", ["text"] = "Binds when picked up\nUse: Deploy a device that can be activated by you or a party or raid member when a crisis is imminent. When activated, it will attempt to resurrect all nearby allies at the end of combat.\n\nLasts for 1 hour or until activation. Must be deployed prior to combat.\nRequires Khaz Algar Engineering (1)\nSell Price:" }
entries[221948] = { ["name"] = "Prototype: Pausing Pylon", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Deploy a Pausing Pylon that will disrupt the natural metabolic processes of players standing nearby, halting the expiration of Khaz Algar Flasks, Phials, and Well Fed effects.\n\nThe pylon is extremely fragile and will detonate in the presence of violence.\nRequires Khaz Algar Engineering (1)\nSell Price:" }
