entries[221956] = { ["name"] = "Prototype: Algari Repair Bot 11O", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Deploy a small earthen golem to allow you and fellow adventurers to repair your equipment.\n\nLasts for 10 min.\nRequires Khaz Algar Engineering (1)\nSell Price:" }
