entries[221958] = { ["name"] = "Prototype: Portable Profession Possibility Projector", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Summon a Possibility Projector configured to satisfy the needs of crafting tables. Only one workbench can be displayed at a time and can only be changed by the Engineer. (10 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:" }
