entries[221960] = { ["name"] = "Prototype: Barrel of Fireworks", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Deploy a dangerous barrel of fireworks for 5 min so you and your friends can violently illuminate the night sky!\n\nOther players can opt-in to seeing the fireworks by attacking the barrel.\n\nCooldown reduced during drunken goblin revelries. (1 Hour Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:" }
entries[221961] = { ["name"] = "Prototype: Defective Escape Pod", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Urgently seek shelter inside a defective escape pod. You won't get very far, but at least you are safe. (10 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:" }
entries[221962] = { ["name"] = "Defective Escape Pod", ["text"] = "Toy\nUse: Urgently seek shelter inside a defective escape pod. You won't get very far, but at least you are safe. (10 Min Cooldown)\nSell Price:" }
entries[221963] = { ["name"] = "Prototype: Filmless Camera", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Embrace your inner photographer! (30 Sec Cooldown)\nSell Price:" }
