entries[221965] = { ["name"] = "Prototype: Wormhole Generator: Khaz Algar", ["text"] = "Binds when picked up\nUnique: Prototype (1)\nUse: Open a wormhole that allows the user to quickly travel to a random location in Khaz Algar. (30 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:" }
entries[221966] = { ["name"] = "Wormhole Generator: Khaz Algar", ["text"] = "Toy\nUse: Open a wormhole that allows the user to quickly travel to a random location in Khaz Algar. (30 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:" }
entries[221967] = { ["name"] = "Crowd Pummeler 2-30", ["text"] = "Mount\n(Account-wide)\nUse: Teaches you how to summon the Crowd Pummeler 2-30.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Guaranteed to knock the teeth out from your enemies with a single punch!\"\nProfession:\nKhaz Algar Engineering" }
entries[221968] = { ["name"] = "Legibly Scribbled Notes", ["text"] = "Binds to Warband\nUse: Arrange 15 Legibly Scribbled Notes into something comprehensible.\nRequires Khaz Algar Engineering (1)\n\"Capable of being read by more than just medics; incapable of being understood by all but engineers.\"" }
entries[221969] = { ["name"] = "P.0.W. x2", ["text"] = "Binds when picked up\nRanged Gun\n3,365 - 6,251 Damage Speed 3.00\n(1,603 damage per second)\n+2,129 Agility\n+9,748 Stamina\n+ 728 Random Stat 1\n+ 728 Random Stat 2\nDurability 120 / 120\n\"Come on, shoot faster!\"\nSell Price:" }
entries[221970] = { ["name"] = "Pure Crawler Extract", ["text"] = "Quest Item\n\"A luminescent green liquid greatly prized by the Machine Speakers for its ability to remove rust.\"" }
entries[221977] = { ["name"] = "Funeral Pyre", ["text"] = "Meta Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nFuneral Pyre\nGrants the caster Primary Stat for 1 min.\n\nEvery 1 sec gain a stack of Funeral Pyre, suffering Fire damage per stack.\n\nFuneral Pyre will be removed early if reactivated. (2 Min Cooldown)\nRequires level 10 to 80 ( 80)\n\"Fits in a Meta socket.\"" }
entries[221982] = { ["name"] = "Bulwark of the Black Ox", ["text"] = "Meta Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nBulwark of the Black Ox\nChannel the Bulwark of the Black Ox. Charge an enemy removing all stuns and roots, gain a shield absorbing damage, and taunt enemies within 20 yards. Every 1 sec for 5 sec inflict Physical damage to enemies within 20 yards plus 20% of damage taken by the shield.\nRequires level 10 to 80 ( 80)\n\"Fits in a Meta socket.\"" }
