entries[222458] = { ["name"] = "Sanctified Steps", ["text"] = "Binds when picked up\nUnique-Equipped: Embellished (2)\nFeet Plate\n4356 Armor\n+1,597 [Strength or Intellect]\n+7,311 Stamina\n+ 546 Versatility\n+ 546 Mastery\nDurability 80 / 80\nEquip: Taking damage has a chance to imbue you with Sanctified Swiftness, granting 46 Speed stacking up to 10 times.\n\nAfter receiving 10 stacks, release the stored energy dealing ( 1 * 374029 ) Holy damage split between all enemies within 10 yards.\nSell Price:" }
