entries[222862] = { ["name"] = "Magically \"Infinite\" Messenger", ["text"] = "Binds when picked up\nUnique\n36 Slot Bag\nEquip: The amount of Resourcefulness, Ingenuity, and Multicraft provided by Shatter Essence is increased by 20.\n\n[ Equip effect requires Khaz Algar Enchanting 1 ][ Equip effect requires Khaz Algar Enchanting 1 ]\n\"Rumors of its infiniteness have been greatly exaggerated.\"\nSell Price:" }
