entries[222988] = { ["name"] = "Elder Glowmite", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nYou must capture at least 120 Glowing Moths before Mothkeeper Wew'tam will trade this item with you.\n\n\"Glowmites slowly grow larger as they age. This one has lived a long, full life.\"\nQuest:\nZone:\nHarandar" }
entries[222989] = { ["name"] = "Cyan Glowmite", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 19 with The Assembly of the Deeps.\nRequires Renown Rank 23 with The Assembly of the Deeps.\n\n\"Glowmites are well-known in the Ringing Deeps for making surprisingly sturdy mounts. This specimen produces a soft cyan glow that kobolds find especially relaxing.\"\nVendor:\nWaxmonger Squick\nZone:\nThe Ringing Deeps\nCost:\n11375" }
