entries[223113] = { ["name"] = "Formula: Enchant Boots - Cavalry's March", ["text"] = "Binds when picked up\nUse: Teaches you how to perform the Cavalry's March enchantment.\nArathor Alterations - Accentuated Accessories\n\nPermanently enchants a pair of boots with the cavalry's fleetness, increasing mounted speed by 0%. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:" }
entries[223114] = { ["name"] = "Formula: Enchant Boots - Scout's March", ["text"] = "Binds when picked up\nUse: Teaches you how to perform the Scout's March enchantment.\nArathor Alterations - Accentuated Accessories\n\nPermanently enchants a pair of boots with a scout's swiftness, increasing Speed by 175. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nRequires Renown Rank 4 with the Hallowfall Arathi.\nRequires Khaz Algar Enchanting and Renown Rank 4 with the Hallowfall Arathi.\nSell Price:" }
