entries[223119] = { ["name"] = "Formula: Enchant Weapon - Authority of Air", ["text"] = "Use: Teaches you how to perform the Authority of Air enchantment.\nArathor Alterations - Fortified Flames\n\nPermanently enchants a weapon with the Authority of Air, which sometimes beckons a protective wind to your aid when taking damage that absorbs the next 204141 damage dealt to you. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:" }
entries[223120] = { ["name"] = "Formula: Enchant Weapon - Authority of Radiant Power", ["text"] = "Use: Teaches you how to perform the Authority of Radiant Power enchantment.\nArathor Alterations - Fortified Flames\n\nPermanently enchants a weapon with the Authority of Radiant Power. Dealing damage has a chance to call upon that authority, smiting your target for ( 1 * 170450) Radiant damage and temporarily increasing your Primary stat by 1560. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:" }
