entries[223126] = { ["name"] = "Formula: Enchant Chest - Stormrider's Agility", ["text"] = "Use: Teaches you how to perform the Stormrider's Agility enchantment.\nEarthen Enhancements - Bolstered Breastplates\n\nPermanently enchants a chestpiece to increase your Agility by 360 and Speed by 180. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:" }
