entries[223144] = { ["name"] = "Formula: Enchant Weapon - Authority of the Depths", ["text"] = "Use: Teaches you how to perform the Authority of the Depths enchantment.\nNerubian Novelties\n\nPermanently enchants a weapon with the Authority of the Depths. Damaging foes may invoke it, applying Suffocating Darkness which periodically inflicts ( 1 * 24502) Shadow damage. The darkness may deepen up to 3 times. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:" }
entries[223145] = { ["name"] = "Marrlok", ["text"] = "Binds to Warband\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[223146] = { ["name"] = "Satchel of Stormborn Seeds", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Plant one of the seeds. (1 Min Cooldown)\n\"A storm's power can be wielded for creation as well as destruction.\"\nSell Price:" }
entries[223153] = { ["name"] = "Reins of the Soaring Meaderbee", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This humble bee dreams of open skies. Whether or not an adventurer is along for the ride is of no consequence to it.\"\nVendor:\nCendvin\nZone:\nThe Isle of Dorn\nCost:\n900" }
entries[223155] = { ["name"] = "Bop", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[223157] = { ["name"] = "Blacksmith's Breastplate", ["text"] = "Quest Item\n\"Faerin recognizes this as belonging to Ryton Blackholme. It is one of his masterpieces. The bloody gouges can leave no doubt as to the blacksmith's fate.\"" }
entries[223158] = { ["name"] = "Raging Cinderbee", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Temper as hot as its flames, this breed of cinderbee can only be tamed by those who share its insatiable penchant for violence.\"\nAchievement:\nRuffious's Bid\nCategory:\nWorld" }
entries[223165] = { ["name"] = "Vengeful Crusader's Helm", ["text"] = "Cosmetic\nBinds to Warband\nHead Plate\n3 Armor\n\"Not recommended for use in mosh pits.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
