entries[223264] = { ["name"] = "Aquamarine Swarmite", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 23 with The Severed Threads.\nRequires Renown Rank 22 with The Severed Threads.\n\n\"While it's not exactly common, the representatives of the Severed Threads assure you that swarmites are more than capable of carrying your weight if you choose to ride it.\"\nVendor:\nLady Vinazian\nZone:\nAzj-Kahet\nCost:\n3940\n\nVendor:\nY'tekhi\nZone:\nAzj-Kahet\nCost:\n3940" }
entries[223265] = { ["name"] = "Nesting Swarmite", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Burrowers by nature they often lurk in small animal warrens when laying eggs or lying in wait to surprise larger prey.\"\nZone:\nVision of Stormwind (Revisited)\nZone:\nVision of Orgrimmar (Revisited)" }
entries[223266] = { ["name"] = "Reins of the Shadowed Swarmite", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Swarmites are a common sight both in the wilds of Azj-Kahet and among the nerubians who have long domesticated them, but that doesn't make them any less dangerous to incautious adventurers.\"\nAchievement:\nGlory of the Nerub-ar Raider\nCategory:\nDungeons & Raids" }
entries[223267] = { ["name"] = "Swarmite Skyhunter", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Typically found in the smallest nooks and crannies of rock ceilings, the swarmite skyhunter is more at home in the air than at rest.\"\nAchievement:\nKhaz Algar Glyph Hunter\nCategory:\nWar Within" }
entries[223269] = { ["name"] = "Machine Defense Unit 1-11", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"One of many such mechsuits designed to guard the Machine. After years of faithful service it is no longer suited for combat. It does make for an impressive conveyance, though.\"\nTreasure:\nAwakened Cache\nZone:\nThe Ringing Deeps" }
entries[223270] = { ["name"] = "Alunira", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"For so long, the very embodiment of the clouds laid trapped atop a mountain of lightning. And at last, I can feel the wind at my back once again.\"\nDrop:\nZone:\nIsle of Dorn" }
entries[223274] = { ["name"] = "Ferocious Jawcrawler", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 22 with The Severed Threads.\nRequires Renown Rank 17 with The Severed Threads.\n\n\"This particularly large jawcrawler is the perfect size to make a mount... just keep your hands and feet clear of its mouth.\"\nVendor:\nLady Vinazian\nZone:\nAzj-Kahet\nCost:\n2815\n\nVendor:\nY'tekhi\nZone:\nAzj-Kahet\nCost:\n2815" }
entries[223276] = { ["name"] = "Widow's Undercrawler", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Conspirator reputation with the Weaver.\n\n\"Surface-dwelling children often profess desires for a pony or wolf of their own upon reaching certain milestones of age. A young Widow Arak'nai had similar ambitions, though her tastes would likely be considered eclectic by some standards.\"\nVendors:\nYamas the Provider, Bobbin\nZone:\nAzj-Kahet\nCost:\n2020" }
entries[223278] = { ["name"] = "Heritage Undercrawler", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Conspirator reputation with the General.\n\n\"Arachnid husbandry is a time-honored tradition amongst the Heritage Forces. Though most specimens are used for transport labor or raised to serve as shock troops, the finest examples of their brood are occasionally trained as parade mounts.\"\nVendors:\nYamas the Provider, Anub'okki, Aspirake Kiipka\nZone:\nAzj-Kahet\nCost:\n2020" }
entries[223279] = { ["name"] = "Royal Court Undercrawler", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Conspirator reputation with the Vizier.\n\n\"Patents of lineage are used to demarcate the history and value of thoroughbred undercrawlers in Kaheti high society. This practice can prove somewhat difficult when said undercrawlers are prone to the sudden consumption of their record-keepers.\"\nVendors:\nYamas the Provider, Tulumun\nZone:\nAzj-Kahet\nCost:\n2020" }
entries[223280] = { ["name"] = "Jade Pearl", ["text"] = "Binds when picked up\nRequires level 70 to 73 ( 73)\n\"A weathered gemstone with a serpent etched upon its surface.\"\nSell Price:" }
