entries[223317] = { ["name"] = "Vermillion Imperial Lynx", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Hallowfall Arathi.\nRequires Renown Rank 21 with the Hallowfall Arathi.\n\n\"Imperial lynxes are considered to be an Arathi's greatest companion, both on and off the battlefield. Sadly, this lynx's previous owner died in battle.\"\nVendor:\nAuralia Steelstrike\nZone:\nHallowfall\nCost:\n8125" }
